package com.franco.desco.application.production.service;import com.franco.desco.application.production.*;import com.franco.desco.application.production.port.in.ProductionUseCase;import com.franco.desco.application.production.port.out.ProductionPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.production.ProductionModels;
public final class ProductionApplicationService implements ProductionUseCase{private final ProductionPersistencePort p;public ProductionApplicationService(ProductionPersistencePort p){this.p=p;}public AppResult<PageResult<ProductionModels.Summary>>list(ProductionCommands.ListProduction c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"PRODUCCION_LISTADA","PRODUCCION_NO_LISTADA",AppStatus.BAD_REQUEST);}public AppResult<ProductionModels.Detail>get(ProductionCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"PRODUCCION_CONSULTADA","PRODUCCION_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(ProductionCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"PRODUCCION_REGISTRADA","PRODUCCION_NO_REGISTRADA");}public AppResult<Void>update(ProductionCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"PRODUCCION_ACTUALIZADA","PRODUCCION_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>confirm(ProductionCommands.Confirm c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.confirm(c,i,m),"PRODUCCION_CONFIRMADA","PRODUCCION_NO_CONFIRMADA",AppStatus.BAD_REQUEST);}public AppResult<Void>discard(ProductionCommands.Discard c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.discard(c,i,m),"PRODUCCION_DESCARTADA","PRODUCCION_NO_DESCARTADA",AppStatus.BAD_REQUEST);}}
